import * as T from './vendor/three.module.js';
import {createCharacter} from './character.js';import {defaults,palettes,styles} from './appearance.js';
// Routes stay on clear pavement lanes; endpoints pause like storefront visits.
export function createPedestrians(scene){const routes=[[-15,7,-6.7],[12,25,-5.6],[30,44,-6.7],[-12,3,18.8],[14,28,18.8],[35,47,18.8]];const people=routes.map(([a,b,z],i)=>{const avatar=createCharacter({...defaults,skin:palettes.skin[i][1],shirt:palettes.shirt[i][1],style:styles[i%5]});avatar.group.position.set(a+(b-a)*.3,.165,z);scene.add(avatar.group);return {...avatar,a,b,z,direction:i%2?1:-1,wait:i*.3,phase:i}});return {people,update(dt,player){for(const p of people){let walking=false;if(p.wait>0)p.wait-=dt;else{const x=p.group.position.x+p.direction*dt*(.85+(p.a%3)*.04);if(Math.hypot(x-player.x,p.z-player.z)>.85){p.group.position.x=x;walking=true;p.phase+=dt*4.5}if(x>=p.b||x<=p.a){p.group.position.x=T.MathUtils.clamp(x,p.a,p.b);p.direction*=-1;p.wait=1.5+Math.abs(p.a%3)}}p.group.rotation.y=p.direction*Math.PI/2;p.legs.forEach((m,i)=>m.rotation.x=walking?Math.sin(p.phase+i*Math.PI)*.4:0);p.arms.forEach((m,i)=>m.rotation.x=walking?-Math.sin(p.phase+i*Math.PI)*.3:0)}}}}
export function createVehicles(scene,colliders){const vehicles=[];for(const [i,x,z,color]of [[0,23,-.8,'#c7b48b'],[1,40,12,'#527d80'],[2,-35,-22,'#a56857']]){const g=new T.Group();g.position.set(x,0,z);scene.add(g);function box(w,h,d,x,y,z,c){const m=new T.Mesh(new T.BoxGeometry(w,h,d),new T.MeshStandardMaterial({color:c,roughness:.55}));m.position.set(x,y,z);g.add(m);return m}box(1.9,.55,4,0,.68,0,color);box(1.65,.65,1.9,0,1.23,-.1,'#344e56');box(1.72,.08,2,0,1.58,-.1,color);box(1.85,.12,3.8,0,.95,0,color);for(const side of [-1,1]){box(.05,.58,.08,side*.84,1.23,0,color);box(.08,.07,.3,side*.96,.98,.3,'#ced1c5');for(const end of [-1.2,1.2]){const wheel=new T.Mesh(new T.CylinderGeometry(.36,.36,.22,12),new T.MeshStandardMaterial({color:'#283231'}));wheel.rotation.z=Math.PI/2;wheel.position.set(side*.94,.4,end);g.add(wheel)}for(const end of [-1,1])box(.5,.16,.04,side*.6,.75,end*2.02,end<0?'#e7e1bb':'#ae5a48')}box(1.8,.14,.15,0,.48,2,'#69736f');colliders.push({x,z,hx:1,hz:2.1});vehicles.push({id:'parked-'+i,name:i===0?'Compact hatchback':'City sedan',group:g,x:x+1.8,z,spawn:{x,z},drivable:false})}return vehicles}
